(function(){const t=document.getElementById("site-navigation");if(!t)return;const e=t.getElementsByTagName("button")[0];if(!e)return;const n=t.getElementsByTagName("ul")[0];if(!n){e.style.display="none";return}n.classList.contains("menu")||n.classList.add("menu"),e.addEventListener("click",function(){t.classList.toggle("toggled");const s=t.classList.contains("toggled");e.setAttribute("aria-expanded",s?"true":"false")}),document.addEventListener("click",function(s){if(!t.classList.contains("toggled"))return;const i=s.target;i instanceof Node&&!t.contains(i)&&(t.classList.remove("toggled"),e.setAttribute("aria-expanded","false"))})})();
